import { PITCH_ROUNDS,makePitchRound,pitchStep } from './pitch-model.js';
import { playPitchPair,stopPitchPair } from './pitch-audio.js';
import { seededRandom } from './challenges.js';
export function setupPitch(stopOtherAudio){
  const $=id=>document.getElementById(id);let active=false,random,staircase,round,index=0,results=[],busy=false,ready=false,answered=false,generation=0;
  function render(){round=makePitchRound(staircase.level,random);ready=false;answered=false;busy=false;$('pitch-round').textContent=`ROUND ${String(index+1).padStart(2,'0')} / 12`;$('pitch-display').textContent='A → B';$('pitch-feedback').textContent='두 음을 듣고 B의 높낮이를 골라주세요.';$('pitch-up').disabled=true;$('pitch-down').disabled=true;$('pitch-play').disabled=false;$('pitch-stop').disabled=true;$('pitch-next').disabled=true;$('pitch-next').textContent=index===11?'결과 보기':'다음 두 음';$('pitch-result').hidden=true;$('pitch-history').replaceChildren(...Array.from({length:12},(_,i)=>{const e=document.createElement('li');e.textContent=String(i+1).padStart(2,'0');e.className=results[i]===undefined?'':results[i].correct?'hit':'miss';return e;}));}
  function cancel(){generation++;stopPitchPair();const interrupted=busy;busy=false;ready=false;$('pitch-stop').disabled=true;$('pitch-play').disabled=answered;$('pitch-up').disabled=true;$('pitch-down').disabled=true;if(interrupted)$('pitch-feedback').textContent='재생 중단 · 다시 들을 수 있습니다.';for(const id of ['pitch-a','pitch-b'])$(id).classList.remove('playing');}
  function reset(){cancel();random=seededRandom(crypto.getRandomValues(new Uint32Array(1))[0]);staircase={level:3,streak:0};index=0;results=[];$('pitch-score').textContent='0';$('session-pitch').textContent='—';render();}
  $('pitch-play').addEventListener('click',async()=>{if(!active||busy||answered)return;stopOtherAudio();const token=++generation;busy=true;ready=false;$('pitch-play').disabled=true;$('pitch-stop').disabled=false;$('pitch-up').disabled=true;$('pitch-down').disabled=true;try{await playPitchPair(round.a,round.b,Number($('pitch-volume').value),phase=>{if(token!==generation)return;for(const label of ['a','b'])$('pitch-'+label).classList.toggle('playing',phase===label);$('pitch-feedback').textContent=phase==='gap'?'잠시 뒤 B가 재생됩니다.':phase==='done'?'B가 A보다 높았나요, 낮았나요?':`${phase.toUpperCase()} 듣는 중`;});if(token!==generation||!active||document.hidden)return;ready=true;$('pitch-up').disabled=false;$('pitch-down').disabled=false;$('pitch-play').textContent='같은 두 음 다시 듣기';}catch(error){if(token===generation)$('pitch-feedback').textContent=error.name==='AbortError'?'재생을 중단했습니다.':'소리를 재생하지 못했습니다. 오디오 기기를 확인하세요.';}finally{if(token===generation){busy=false;$('pitch-play').disabled=answered;$('pitch-stop').disabled=true;}}});
  for(const [id,higher] of [['pitch-up',true],['pitch-down',false]])$(id).addEventListener('click',()=>{if(!ready||busy||answered||!active)return;answered=true;const correct=higher===round.higher;results.push({correct,cents:round.cents});staircase=pitchStep(staircase,correct);$('pitch-up').disabled=true;$('pitch-down').disabled=true;$('pitch-play').disabled=true;$('pitch-next').disabled=false;$('pitch-score').textContent=results.filter(r=>r.correct).length;$('pitch-display').textContent=round.higher?'A ↗ B':'A ↘ B';$('pitch-feedback').textContent=`${correct?'정답':'오답'} · B가 ${round.higher?'높았습니다':'낮았습니다'}. ${round.cents}센트 차이 · A ${round.a.toFixed(1)} / B ${round.b.toFixed(1)} Hz`;$('pitch-history').children[index].className=correct?'hit':'miss';$('pitch-next').focus({preventScroll:true});});
  $('pitch-next').addEventListener('click',()=>{if(!answered)return;if(index<PITCH_ROUNDS-1){index++;render();$('pitch-play').focus({preventScroll:true});}else{$('pitch-next').disabled=true;const count=results.filter(r=>r.correct).length,smallest=Math.min(...results.filter(r=>r.correct).map(r=>r.cents));$('pitch-result').hidden=false;$('pitch-result').textContent=`${count}/12 정답 · 이번 정답 중 가장 작은 차이 ${Number.isFinite(smallest)?smallest+'센트':'—'}`;$('session-pitch').textContent=`${count}/12`;$('pitch-feedback').textContent='12라운드 완료';}});
  $('pitch-stop').addEventListener('click',cancel);$('pitch-restart').addEventListener('click',reset);$('pitch-volume').addEventListener('input',()=>{cancel();$('pitch-volume-output').value=$('pitch-volume').value;});
  reset();return {select(name){if(name!=='pitch')cancel();active=name==='pitch';},cancel};
}
